def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    strong_prev = []
    desperate_count = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev['bid']
                prev_bids.append(bid)
                if bid >= 100:
                    strong_prev.append(bid)

    if not alive_opps:
        return float(min(budget, 20.0))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water >= 2:
        urgency += 1.0
    elif no_water >= 1:
        urgency += 0.45

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    if strong_prev:
        target_high = max(strong_prev)
    else:
        target_high = highest_prev

    if urgency >= 1.4:
        bid = max(110.0, target_high + 2.0, avg_prev + 8.0)
    elif scarcity > 0.7:
        bid = max(85.0, avg_prev + 5.0)
        if target_high >= 120:
            bid = max(bid, min(target_high + 1.0, 155.0))
    elif scarcity > 0.4:
        bid = max(52.0, avg_prev * 0.72 + 4.0)
    else:
        bid = max(28.0, avg_prev * 0.45 + 2.0)

    if desperate_count >= 2:
        bid += 10.0
    elif desperate_count == 1:
        bid += 5.0

    if day >= 8 and hp <= 5:
        bid += 12.0

    if budget < 120:
        bid = min(bid, max(25.0, budget * 0.72))
    elif budget < 220:
        bid = min(bid, budget * 0.82)

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append((opp_id, opp))

    # If no opponents are alive, conserve.
    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids (immediate reaction only).
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Determine pressure from yesterday.
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_highest = 0.0
    if yesterday_bids:
        sorted_bids = sorted(yesterday_bids, reverse=True)
        if len(sorted_bids) > 1:
            second_highest = sorted_bids[1]

    # Estimate scarcity: higher supply reduces urgency.
    scarcity = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)  # 0..1
    scarcity = max(0.0, min(1.0, scarcity))

    # Base bid: mid-high to outbid strong contenders, but not chase the very top.
    # Target slightly above the 2nd-highest when pressure is high.
    pressure = 0.0
    if highest_prev_bid > 0:
        pressure = min(1.0, highest_prev_bid / (DAILY_SALARY * 1.6))

    # If our hp is low or we have consecutive no-water days, we must secure water.
    urgent = (hp <= 3.0) or (no_water_days >= 2)

    if urgent:
        # Escalate aggressively but cap by budget.
        target = max(DAILY_SALARY * 0.75, second_highest + 2.0, highest_prev_bid * 0.92)
    else:
        # Non-urgent: bid enough to beat the mid/high pack.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(DAILY_SALARY * (0.55 + 0.2 * scarcity), second_highest + 1.5)
        else:
            target = max(DAILY_SALARY * (0.45 + 0.25 * scarcity), highest_prev_bid * 0.6)

    # Small strategic edge: if supply is tight, add a little.
    target *= (1.0 + 0.06 * scarcity)

    # Ensure within budget and non-negative.
    bid = max(0.0, min(budget, float(target)))

    # If budget is extremely low, still bid minimal to avoid total waste.
    if bid < 1e-6:
        bid = min(budget, DAILY_SALARY * 0.1)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid minimum to get water and save budget
    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    # Get yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine if supply is tight for the number of competitors
    total_expected_water_demand = WATER_REQ
    for opp in alive_opponents:
        total_expected_water_demand += opp['water_requirement']

    is_supply_sufficient_for_all = day_context['supply'] >= total_expected_water_demand

    # CRITICAL: If HP is very low or no water for days, bid aggressively to survive
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        return min(my_status['budget'], DAILY_SALARY * 0.99)

    # If no previous bids from opponents (e.g., Day 1 or they didn't bid), use a default strategy
    if not yesterday_bids:
        if is_supply_sufficient_for_all:
            # Enough for everyone, bid moderately low to test the waters
            return min(my_status['budget'], DAILY_SALARY * 0.3)
        else:
            # Scarcity, bid moderately high to secure water
            return min(my_status['budget'], DAILY_SALARY * 0.6)

    # Strategy based on yesterday's bids and current state
    highest_prev_bid = max(yesterday_bids)
    lowest_prev_bid = min(yesterday_bids)
    average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

    # Check for high pressure from opponents (if their highest bid was very high)
    high_pressure_from_opponents = highest_prev_bid >= DAILY_SALARY * 0.85

    # If supply is tight (not enough for everyone)
    if not is_supply_sufficient_for_all:
        if my_status['hp'] <= 4: # Low HP, need water urgently but not critical
            # Bid slightly above highest previous bid or high default if no high pressure
            return min(my_status['budget'], highest_prev_bid + 5 if high_pressure_from_opponents else DAILY_SALARY * 0.85)
        else: # HP is okay, but supply is tight, need to compete
            if high_pressure_from_opponents:
                # Opponents are bidding high, I need to match or slightly exceed to win
                return min(my_status['budget'], highest_prev_bid + 2)
            else:
                # Opponents not bidding too high, but supply is tight, bid above average
                return min(my_status['budget'], max(average_prev_bid + 10, DAILY_SALARY * 0.7))

    # If supply is sufficient for all, try to save money
    else:
        if my_status['hp'] <= 3: # Still low HP, even with sufficient supply, ensure win
            # Bid slightly above highest previous bid to be safe, but not too high
            return min(my_status['budget'], max(highest_prev_bid + 1, DAILY_SALARY * 0.5))
        else:
            # Enough water, bid just above the lowest previous bid or a safe low amount to save budget
            return min(my_status['budget'], max(lowest_prev_bid + 1, DAILY_SALARY * 0.25))

    # Fallback bid (should not be reached under normal circumstances)
    return min(my_status['budget'], DAILY_SALARY * 0.5)

